B.a_a=s(["Proper diary, that! You write better than I talk.","\u062f\u0641\u062a\u0631\u0686\u0647\u0654 \u062f\u0631\u0633\u062a\u200c\u0648\u062d\u0633\u0627\u0628\u06cc\u0647! \u0628\u0647\u062a\u0631 \u0627\u0632 \u062d\u0631\u0641 \u0632\u062f\u0646 \u0645\u0646 \u0645\u06cc\u200c\u0646\u0648\u06cc\u0633\u06cc."],t.s)
B.ZI=s(["Cracking entry. Put the kettle on and tell me more.","\u0646\u0648\u0634\u062a\u0647\u0654 \u0645\u0639\u0631\u06a9\u0647\u200c\u0627\u06cc \u0628\u0648\u062f. \u06a9\u062a\u0631\u06cc \u0631\u0648 \u0628\u0630\u0627\u0631 \u0648 \u0628\u06cc\u0634\u062a\u0631 \u0628\u06af\u0648."],t.s)
B.XJ=s([B.a_a,B.ZI],t.rj)
B.Y6=s(["Oh, that is lovely. Thank you for sharing it with me.","\u0648\u0627\u06cc\u060c \u062e\u06cc\u0644\u06cc \u0642\u0634\u0646\u06af\u0647. \u0645\u0645\u0646\u0648\u0646 \u06a9\u0647 \u0628\u0627 \u0645\u0646 \u062f\u0631\u0645\u06cc\u0648\u0646\u0634 \u06af\u0630\u0627\u0634\u062a\u06cc."],t.s)
B.ZF=s(["Beautifully written \u2014 I might pin it on the fridge!","\u062e\u06cc\u0644\u06cc \u0632\u06cc\u0628\u0627 \u0646\u0648\u0634\u062a\u06cc \u2014 \u0634\u0627\u06cc\u062f \u0628\u0686\u0633\u0628\u0648\u0646\u0645\u0634 \u0631\u0648 \u06cc\u062e\u0686\u0627\u0644!"],t.s)
B.Yy=s([B.Y6,B.ZF],t.rj)
B.XZ=s(["I can read that! Well, nearly. Teddy says it's brilliant.","\u0645\u0646 \u0645\u06cc\u200c\u062a\u0648\u0646\u0645 \u0628\u062e\u0648\u0646\u0645\u0634! \u062e\u0628\u060c \u062a\u0642\u0631\u06cc\u0628\u0627\u064b. \u062e\u0631\u0633\u06cc \u0645\u06cc\u200c\u06af\u0647 \u0639\u0627\u0644\u06cc\u0647."],t.s)
B.a_s=s([B.XZ],t.rj)
B.a_8=s(["Not gonna lie, that's actually decent, mate.","\u062f\u0631\u0648\u063a \u0646\u06af\u0645\u060c \u0648\u0627\u0642\u0639\u0627\u064b \u062e\u0648\u0628\u0647 \u0631\u0641\u06cc\u0642."],t.s)
B.Ye=s([B.a_8],t.rj)
B.Xp=s(["You've a way with words, pet. Mind you, so did I at your age.","\u0628\u0627 \u06a9\u0644\u0645\u0627\u062a \u062e\u0648\u0628 \u0628\u0627\u0632\u06cc \u0645\u06cc\u200c\u06a9\u0646\u06cc \u0639\u0632\u06cc\u0632\u0645. \u0627\u0644\u0628\u062a\u0647 \u0645\u0646\u0645 \u0647\u0645\u200c\u0633\u0646 \u062a\u0648 \u0647\u0645\u06cc\u0646\u200c\u0637\u0648\u0631 \u0628\u0648\u062f\u0645."],t.s)
B.a_n=s([B.Xp],t.rj)
